"""Apply a JSON Patch (RFC 6902) to a JSON document. See task.md."""

from __future__ import annotations

import re
from typing import Any


class PatchError(ValueError):
    """Raised when a patch is malformed or cannot be applied."""


_INDEX = re.compile(r"(?:0|[1-9][0-9]*)\Z")
_BAD_ESCAPE = re.compile(r"~(?![01])")
_OPS = {"add", "remove", "replace", "move", "copy", "test"}


def _clone(value: Any) -> Any:
    if isinstance(value, dict):
        return {k: _clone(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_clone(v) for v in value]
    return value


def _parse(pointer: str) -> list[str]:
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise PatchError(f"invalid pointer {pointer!r}")
    tokens = pointer[1:].split("/")
    out = []
    for tok in tokens:
        if _BAD_ESCAPE.search(tok):
            raise PatchError(f"invalid escape in pointer {pointer!r}")
        out.append(tok.replace("~1", "/").replace("~0", "~"))
    return out


def _index(tok: str, length: int, *, allow_end: bool = False) -> int:
    if not _INDEX.match(tok):
        raise PatchError(f"invalid array index {tok!r}")
    i = int(tok)
    if i > length or (i == length and not allow_end):
        raise PatchError(f"array index {tok!r} out of range")
    return i


def _get(doc: Any, tokens: list[str]) -> Any:
    cur = doc
    for tok in tokens:
        if isinstance(cur, dict):
            if tok not in cur:
                raise PatchError(f"no member {tok!r}")
            cur = cur[tok]
        elif isinstance(cur, list):
            cur = cur[_index(tok, len(cur))]
        else:
            raise PatchError("cannot descend into a scalar")
    return cur


def _add(doc: Any, tokens: list[str], value: Any) -> Any:
    if not tokens:
        return value
    parent = _get(doc, tokens[:-1])
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = value
    elif isinstance(parent, list):
        if last == "-":
            parent.append(value)
        else:
            parent.insert(_index(last, len(parent), allow_end=True), value)
    else:
        raise PatchError("parent is not a container")
    return doc


def _remove(doc: Any, tokens: list[str]) -> tuple[Any, Any]:
    if not tokens:
        raise PatchError("cannot remove the whole document")
    parent = _get(doc, tokens[:-1])
    last = tokens[-1]
    if isinstance(parent, dict):
        if last not in parent:
            raise PatchError(f"no member {last!r}")
        return doc, parent.pop(last)
    if isinstance(parent, list):
        return doc, parent.pop(_index(last, len(parent)))
    raise PatchError("parent is not a container")


def _replace(doc: Any, tokens: list[str], value: Any) -> Any:
    if not tokens:
        return value
    parent = _get(doc, tokens[:-1])
    last = tokens[-1]
    if isinstance(parent, dict):
        if last not in parent:
            raise PatchError(f"no member {last!r}")
        parent[last] = value
    elif isinstance(parent, list):
        parent[_index(last, len(parent))] = value
    else:
        raise PatchError("parent is not a container")
    return doc


def _equal(a: Any, b: Any) -> bool:
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, (int, float)):
        return isinstance(b, (int, float)) and a == b
    if isinstance(a, str):
        return isinstance(b, str) and a == b
    if a is None:
        return b is None
    if isinstance(a, list):
        return (
            isinstance(b, list)
            and len(a) == len(b)
            and all(_equal(x, y) for x, y in zip(a, b))
        )
    if isinstance(a, dict):
        return (
            isinstance(b, dict)
            and a.keys() == b.keys()
            and all(_equal(v, b[k]) for k, v in a.items())
        )
    return False


def apply(document: Any, patch: list[dict]) -> Any:
    """Return the result of applying `patch` to `document`."""
    if not isinstance(patch, list):
        raise PatchError("patch must be a list")
    doc = _clone(document)
    for op in patch:
        if not isinstance(op, dict):
            raise PatchError("operation must be an object")
        name = op.get("op")
        if not isinstance(name, str) or name not in _OPS:
            raise PatchError(f"invalid op {name!r}")
        path = op.get("path")
        if not isinstance(path, str):
            raise PatchError("path missing or not a string")
        src = None
        if name in ("move", "copy"):
            src = op.get("from")
            if not isinstance(src, str):
                raise PatchError("from missing or not a string")
        if name in ("add", "replace", "test") and "value" not in op:
            raise PatchError("value missing")

        tokens = _parse(path)
        if name == "add":
            doc = _add(doc, tokens, _clone(op["value"]))
        elif name == "remove":
            doc, _ = _remove(doc, tokens)
        elif name == "replace":
            doc = _replace(doc, tokens, _clone(op["value"]))
        elif name == "test":
            if not _equal(_get(doc, tokens), op["value"]):
                raise PatchError("test failed")
        else:
            from_tokens = _parse(src)
            if name == "copy":
                doc = _add(doc, tokens, _clone(_get(doc, from_tokens)))
            else:
                if src == path:
                    _get(doc, from_tokens)
                    continue
                if path.startswith(src + "/"):
                    raise PatchError("cannot move a value into its own child")
                doc, value = _remove(doc, from_tokens)
                doc = _add(doc, tokens, value)
    return doc
